", "HelperB.dfy": "    H.Prove(a,b,c,d,s);
    var u := if a < s - d then s - d else a;
    var v := s - u;
    if a < s - d {
      assert u == s - d;
      assert u + u + g <= s;
    } else {
      assert u == a;
      assert u + u + g <= s;
    }
    assert u + g <= v;
    O.Gap(g,u,v);
    A.Finish(a,b,c,d,s,g,u,v);
